import React from "react";
import { useNavigate } from "react-router-dom";
import "./StudentDashboard.css";

const StudentDashboard = () => {
  const navigate = useNavigate();

  return (
    <div className="dashboard-container">
      {/* Welcome */}
      <h1 className="dashboard-title">Welcome Student 👋</h1>
      <p className="dashboard-subtitle">
        Explore college events, register and track your activities
      </p>

      {/* Quick Actions */}
      <div className="dashboard-cards">
        <div className="dash-card" onClick={() => navigate("/events")}>
          <h3>All Events</h3>
          <p>View & register for events</p>
        </div>

        <div className="dash-card" onClick={() => navigate("/myevents")}>
          <h3>My Events</h3>
          <p>Registered events</p>
        </div>

        <div className="dash-card" onClick={() => navigate("/calendar")}>
          <h3>Calendar</h3>
          <p>Event schedule</p>
        </div>

        <div className="dash-card" onClick={() => navigate("/map")}>
          <h3>Campus Map</h3>
          <p>Find seminar halls</p>
        </div>
      </div>
    </div>
  );
};

export default StudentDashboard;
